mapper.update:
UPDATE TBTS_SAMPLE_BOARD /* BoardMapper.updateBoard */
   SET TITLE     = #{b.title}
     , CONTENT   = #{b.content}
     , WRITER_NM = #{b.writerNm}
     , UP_EMP_CD = #{userId}
     , UP_DTM    = NOW()
 WHERE MB_ID = #{mbId}
   AND SEQ = #{b.seq}
   AND USE_YN = 'Y'

UPDATE TBTS_SAMPLE_BOARD /* BoardMapper.deleteBoard 삭제는 사용여부 N */
   SET USE_YN    = 'N'
     , UP_EMP_CD = #{userId}
     , UP_DTM    = NOW()
 WHERE MB_ID = #{mbId}
   AND SEQ = #{seq}
   AND USE_YN = 'Y'
